import seaborn as sns
import matplotlib.pyplot as plt
import matplotlib
import numpy as np
import pandas as pd
import matplotlib.gridspec as gridspec

# Set seed for generating noise
np.random.seed(42)

sns.set(style="darkgrid", palette="colorblind")
colors = sns.color_palette("colorblind")

def sensitivity(estimator, n, k, eta):
    if estimator == 'G-formula':
        deltaeq = 4
        deltaother = 4
    if estimator == 'IPW':
        deltaeq = 2/eta
        deltaother = 1/eta
    if estimator == 'AIPW':
        deltaeq = 4/eta
        deltaother = 2/eta + 2
    return deltaeq/n + deltaother/k # This assumes that k divides n

# Adds noise to non-private ATE estimates
def add_noise(results, sens, mu):
    return [ate + np.random.normal(scale = sens/mu) for ate in results]


def violinplots(data_map1, data_map2, title = "Experiment", filename = None):
    labels1, data1 = zip(*data_map1.items())
    labels2, data2 = zip(*data_map2.items())

    fig = plt.figure(figsize=(28, 7))
    gs = gridspec.GridSpec(1, 2, width_ratios=[10, 10]) 

    # First plot
    ax1 = fig.add_subplot(gs[0])
    sns.violinplot(data=data1, inner='box', linewidth=1.2, ax=ax1)

    # Set colors and hatches
    styles1 = [
        { 'facecolor':sns.desaturate(colors[0], 0.75), "hatch": "/" },
        { 'facecolor':sns.desaturate(colors[0], 0.75), "hatch": "//" },
        { 'facecolor':sns.desaturate(colors[0], 0.75), "hatch": "///" },
        { 'facecolor':sns.desaturate(colors[1], 0.75), "hatch": "\\" },
        { 'facecolor':sns.desaturate(colors[1], 0.75), "hatch": "\\\\" },
        { 'facecolor':sns.desaturate(colors[1], 0.75), "hatch": "\\\\\\" },
        { 'facecolor':sns.desaturate(colors[3], 0.75) },
        { 'facecolor':sns.desaturate(colors[2], 0.75) },
              ]
    for violin, style in zip(ax1.collections, styles1):
        violin.set(**style)

    # Add line and text between prior methods and us
    split_pos = 5.5
    ax1.axvline(x=split_pos, color="black", linewidth=1)
    ymin, ymax = ax1.get_ylim()
    ax1.text(5.45, ymin + (ymax-ymin)*0.04, "Prior methods", ha="right", va="bottom", fontsize=18, fontweight="bold")
    ax1.text(4.4, ymin + (ymax-ymin)*0.042, r"$\longleftarrow$", ha="right", va="bottom", fontsize=18, fontweight="bold")
    ax1.text(5.55, ymin + (ymax-ymin)*0.04, "Our Techniques", ha="left", va="bottom", fontsize=18, fontweight="bold")
    ax1.text(6.7, ymin + (ymax-ymin)*0.042, r"$\longrightarrow$", ha="left", va="bottom", fontsize=18, fontweight="bold")

    ax1.set_xticklabels(labels1, fontsize=18)
    ax1.axhline(0.10, color='black', linestyle='--', label=r'True treatment effect $\tau$')
    ax1.set_ylabel("Estimated treatment effect", fontsize=20)
    ax1.legend(fontsize=20)
    plt.yticks(fontsize=16)

    # Second plot
    ax2 = fig.add_subplot(gs[1])
    sns.violinplot(data=data2, inner='box', linewidth=1.2, ax=ax2)

    # Set colors and hatches
    styles2 = [
        { 'facecolor':sns.desaturate(colors[0], 0.75)},
        { 'facecolor':sns.desaturate(colors[1], 0.75)},
        { 'facecolor':sns.desaturate(colors[4], 0.75), "hatch": ".."},
        { 'facecolor':sns.desaturate(colors[4], 0.75), "hatch": "//"},
        { 'facecolor':sns.desaturate(colors[3], 0.75), "hatch": ".."},
        { 'facecolor':sns.desaturate(colors[3], 0.75), "hatch": "//"},
        { 'facecolor':sns.desaturate(colors[2], 0.75), "hatch": ".." },
        { 'facecolor':sns.desaturate(colors[2], 0.75), "hatch": "\\\\" },
        { 'facecolor':sns.desaturate(colors[2], 0.75), "hatch": "--" },
        { 'facecolor':sns.desaturate(colors[2], 0.75), "hatch": "//" },
              ]
    for violin, style in zip(ax2.collections, styles2):
        violin.set(**style)

    # Add line and text between prior methods and us
    split_pos = 1.5
    ax2.axvline(x=split_pos, color="black", linewidth=1)
    ymin, ymax = ax2.get_ylim()
    ax2.text(1.45, ymin + (ymax-ymin)*0.04, "Prior methods", ha="right", va="bottom", fontsize=18, fontweight="bold")
    ax2.text(0.14, ymin + (ymax-ymin)*0.042, r"$\longleftarrow$", ha="right", va="bottom", fontsize=18, fontweight="bold")
    ax2.text(1.55, ymin + (ymax-ymin)*0.04, "Our Techniques", ha="left", va="bottom", fontsize=18, fontweight="bold")
    ax2.text(2.97, ymin + (ymax-ymin)*0.042, r"$\longrightarrow$", ha="left", va="bottom", fontsize=18, fontweight="bold")

    ax2.set_xticklabels(labels2, fontsize=18)
    ax2.axhline(0.20, color='black', linestyle='--', label=r'True treatment effect $\tau$')
    ax2.legend(fontsize=20)
    plt.yticks(fontsize=16)

    plt.tight_layout()
    if filename:
        plt.savefig(filename)
    plt.show()

